type HFTelemetryPacket struct {
	TickNumber int64
	Requests   int64
	Duration   time.Duration
}

func RunHighFrequencyPumper(ctx context.Context, reqCounter *int64, out chan<- HFTelemetryPacket) {
	ticker := time.NewTicker(20 * time.Millisecond) // Масштабировано для быстрого теста
	defer ticker.Stop()

	var tick int64
	for {
		select {
		case <-ctx.Done():
			return
		case <-ticker.C:
			tick++
			// Атомарно забираем и сбрасываем счетчик за тик
			reqs := atomic.SwapInt64(reqCounter, 0)
			out <- HFTelemetryPacket{
				TickNumber: tick,
				Requests:   reqs,
			}
		}
	}
}

func TestHighFrequencyMetricsPumper(t *testing.T) {
	var counter int64
	out := make(chan HFTelemetryPacket, 10)

	ctx, cancel := context.WithTimeout(context.Background(), 80*time.Millisecond)
	defer cancel()

	// Накручиваем счетчик
	atomic.AddInt64(&counter, 150)

	go RunHighFrequencyPumper(ctx, &counter, out)

	p1 := <-out
	if p1.Requests != 150 {
		t.Fatalf("Первый тик должен забрать 150 запросов, получено: %d", p1.Requests)
	}

	fmt.Println("Высокочастотный агрегатор метрик успешно отработал:")
	fmt.Printf("  • Тик #%d: сагрегировано %d запросов за интервал\n", p1.TickNumber, p1.Requests)
}

package main

import (
	"fmt"
	"sync"
	"testing"
	"time"
)

type FieldEdit struct {
	Value     string
	Timestamp int64
	AuthorID  string
}

type CRDTDocument struct {
	mu     sync.RWMutex
	fields map[string]FieldEdit
}

func NewCRDTDocument() *CRDTDocument {
	return &CRDTDocument{fields: make(map[string]FieldEdit)}
}

// Merge по правилу Last-Write-Wins (LWW)
func (d *CRDTDocument) ApplyEdit(field string, edit FieldEdit) bool {
	d.mu.Lock()
	defer d.mu.Unlock()

	current, exists := d.fields[field]
	if !exists || edit.Timestamp > current.Timestamp || (edit.Timestamp == current.Timestamp && edit.AuthorID > current.AuthorID) {
		d.fields[field] = edit
		return true // Правка принята
	}
	return false // Отклонена как устаревшая
}

func (d *CRDTDocument) GetField(field string) string {
	d.mu.RLock()
	defer d.mu.RUnlock()
	return d.fields[field].Value
}

func TestCRDTDocumentCollaboration(t *testing.T) {
	doc := NewCRDTDocument()

	t1 := time.Now().UnixNano()
	t2 := t1 + 1000 // Более поздняя правка

	// Пользователь А вносит правку со старым временем
	editA := FieldEdit{
		Value:     "Архитектура Go 1.23",
		Timestamp: t1,
		AuthorID:  "Alice",
	}

	// Пользователь Б вносит правку с более свежим временем
	editB := FieldEdit{
		Value:     "Архитектура Go 1.24 (Релизная)",
		Timestamp: t2,
		AuthorID:  "Bob",
	}

	// Симулируем доставку в произвольном сетевом порядке: сначала B, потом A!
	doc.ApplyEdit("title", editB)
	doc.ApplyEdit("title", editA) // Должно быть отклонено, так как t1 < t2!

	finalTitle := doc.GetField("title")
	expected := "Архитектура Go 1.24 (Релизная)"

	if finalTitle != expected {
		t.Fatalf("CRDT конфликт разрешен неверно: got %s, want %s", finalTitle, expected)
	}

	fmt.Println("CRDT (Last-Write-Wins) коллаборативный редактор успешно протестирован:")
	fmt.Printf("  • Итоговое значение документа: «%s»\n", finalTitle)
	fmt.Println("  • Конфликт одновременных правок разрешен детерминированно без блокировок!")
}

package main

import (
	"fmt"
	"sync"
	"testing"
)

type TicTacToeGame struct {
	mu         sync.Mutex
	board      [9]string // "", "X", "O"
	turnPlayer string    // "X" или "O"
	winner     string
	spectators []chan string
}

func NewGame() *TicTacToeGame {
	return &TicTacToeGame{
		turnPlayer: "X",
	}
}

func (g *TicTacToeGame) MakeMove(player string, cell int) error {
	g.mu.Lock()
	defer g.mu.Unlock()

	if g.winner != "" {
		return fmt.Errorf("игра уже завершена победой %s", g.winner)
	}
	if player != g.turnPlayer {
		return fmt.Errorf("ход не вашей очереди (Anti-Cheat)")
	}
	if cell < 0 || cell > 8 {
		return fmt.Errorf("невалидная ячейка")
	}
	if g.board[cell] != "" {
		return fmt.Errorf("клетка %d уже занята (Anti-Cheat)", cell)
	}

	g.board[cell] = player

	// Переключаем ход
	if g.turnPlayer == "X" {
		g.turnPlayer = "O"
	} else {
		g.turnPlayer = "X"
	}

	// Оповещаем зрителей
	snapshot := fmt.Sprintf("Ход: %s в клетку %d", player, cell)
	for _, spec := range g.spectators {
		select {
		case spec <- snapshot:
		default:
		}
	}
	return nil
}

func (g *TicTacToeGame) AddSpectator() chan string {
	g.mu.Lock()
	defer g.mu.Unlock()
	ch := make(chan string, 10)
	g.spectators = append(g.spectators, ch)
	return ch
}

func TestMultiplayerGameAntiCheat(t *testing.T) {
	game := NewGame()
	specChan := game.AddSpectator()

	// 1. Игрок X ходит в клетку 0 -> успешно
	if err := game.MakeMove("X", 0); err != nil {
		t.Fatalf("Ошибка валидного хода: %v", err)
	}

	// 2. Игрок X пытается сходить второй раз подряд (Читерство!) -> сервер блокирует
	errCheat1 := game.MakeMove("X", 1)
	if errCheat1 == nil {
		t.Fatal("Ожидался отказ для хода вне очереди")
	}

	// 3. Игрок O пытается сходить в занятую клетку 0 (Читерство!) -> сервер блокирует
	errCheat2 := game.MakeMove("O", 0)
	if errCheat2 == nil {
		t.Fatal("Ожидался отказ для хода в занятую клетку")
	}

	// 4. Игрок O ходит валидно в клетку 4
	if err := game.MakeMove("O", 4); err != nil {
		t.Fatalf("Ошибка валидного хода O: %v", err)
	}

	// Проверяем, что зритель получил трансляцию ходов
	m1 := <-specChan
	m2 := <-specChan

	fmt.Println("Игровой сервер успешно защитил правила от читерства:")
	fmt.Printf("  • Попытка двойного хода заблокирована: %v\n", errCheat1)
	fmt.Printf("  • Попытка перезаписи занятой клетки заблокирована: %v\n", errCheat2)
	fmt.Printf("  • Зритель получил ходы: «%s» и «%s»\n", m1, m2)
}

